"""settings.py 를 처음 상태로 되돌립니다.

쓰는 때: 값을 이것저것 바꾸다가 무엇이 원래 값이었는지 모르게 됐을 때.
쓰는 법: 터미널에서  python reset.py
결과:   settings.py 가 USE_HISTORY = False / HISTORY_TURNS = 1 로 돌아갑니다.
"""
ORIGINAL = '# ================================================================\n#  오늘 바꾸는 파일은 이것 하나입니다.  app.py 는 열지 않습니다.\n#\n#  바꾸는 법\n#    1) 아래 값을 고칩니다\n#    2) Ctrl + S 로 저장합니다\n#    3) 터미널에서 Ctrl + C 로 앱을 끕니다\n#    4) Run Task > 봇 실행 을 다시 누릅니다\n#  저장만 하고 재실행하지 않으면 화면은 그대로입니다.\n# ================================================================\n\n\n# ----------------------------------------------------------------\n#  1. 앞 대화를 봇에게 건넬까요?\n#\n#     False = 방금 친 말 한 개만 건넵니다\n#     True  = 앞 대화까지 함께 건넵니다\n#\n#     채팅창에 앞 대화가 보이는 것과, 봇에게 건네는 것은 다릅니다.\n#     이 값이 False 이면 화면에 열 줄이 있어도 봇은 한 개만 받습니다.\n#\n#     넣을 수 있는 값: True 또는 False  (따옴표 없이, 첫 글자 대문자)\n# ----------------------------------------------------------------\nUSE_HISTORY = False\n\n\n# ----------------------------------------------------------------\n#  2. 건넨다면 최근 몇 번의 주고받기까지 건널까요?\n#\n#     1 = 바로 앞 한 번의 주고받기(내 말 + 봇의 답)만 건넵니다\n#     5 = 최근 다섯 번의 주고받기를 건넵니다\n#\n#     위 USE_HISTORY 가 False 이면 이 값은 쓰이지 않습니다.\n#\n#     넣을 수 있는 값: 0 이상의 정수\n#     0 을 넣으면 앞 대화를 하나도 건네지 않습니다(False 와 같아집니다)\n# ----------------------------------------------------------------\nHISTORY_TURNS = 1\n'

open("settings.py", "w", encoding="utf-8").write(ORIGINAL)
print("settings.py 를 처음 상태로 되돌렸습니다.")
print("  USE_HISTORY   = False")
print("  HISTORY_TURNS = 1")
print("터미널에서 Run Task > 봇 실행 을 다시 눌러 주세요.")
